# Save my transform function to memory
def transform_final(grid):
    n, m = len(grid), len(grid[0])

    def get_neighbors(r, c):
        return [grid[r+dr][c+dc] for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                if 0 <= r+dr < n and 0 <= c+dc < m and grid[r+dr][c+dc] != 0]

    all_cells = {(r, c) for r in range(n) for c in range(m) if grid[r][c] != 0}
    isolated_targets = [(r, c) for r in range(n) for c in range(m) 
                        if grid[r][c] != 0 and len(get_neighbors(r, c)) == 0]

    pattern_cells = all_cells - set(isolated_targets)
    pattern_5s = [(r, c) for r, c in pattern_cells if grid[r][c] == 5]

    if pattern_cells and isolated_targets and pattern_5s:
        anchor = pattern_5s[0]
        target = isolated_targets[0]
        row_shift = target[0] - anchor[0] 
        col_shift = target[1] - anchor[1]

        def transform_shift(r, c):
            if grid[r][c] == 5:
                return 1
            return grid[r][c]

        output = [[0] * m for _ in range(n)]

        for rr, cc in pattern_cells:
            output[rr][cc] = grid[rr][cc]

        for rr, cc in pattern_cells:
            val = transform_shift(rr, cc)
            nr, nc = rr + row_shift, cc + col_shift
            if 0 <= nr < n and 0 <= nc < m:
                output[nr][nc] = val

        for r, c in isolated_targets:
            output[r][c] = 0

        return output
    else:
        return grid

transform_final = transform_final
